csv_path = 'text_csv/categories/entry_00246_Main_Story_Cutscenes_Dialogues.csv'
with open(csv_path, mode='r', encoding='utf-8-sig') as f:
    rows = list(csv.DictReader(f))
    fieldnames = rows[0].keys()

updated_count = 0
for idx, text in translations.items():
    if idx < len(rows):
        rows[idx]['ThaiTranslation'] = text
        updated_count += 1

with open(csv_path, mode='w', encoding='utf-8-sig', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=fieldnames)
    writer.writeheader()
    writer.writerows(rows)

print(f"[SUCCESS] Updated {updated_count} lines (1000-1249) in {csv_path}")
